const std = @import("std"); const ctx3 = @import("ct-ctrl-ctxz.zig"); const walk = @import("ru-page-walk.zig"); const expo = @import("ct-expo-data.zig"); const exit = @import("ct-exit-code.zig"); const cana = @import("ru-cana-chec.zig"); const pipe = @import("ru-page-fetc.zig"); const file = @import("st-stor-file.zig"); const inde = @import("st-page-inde.zig"); const base = @import("nt-vend-base.zig"); const spen = @import("ru-spen-guar.zig"); const cfgz = @import("cf-conf-load.zig"); const clou = @import("ct-ctrl-clou.zig"); const hash = @import("ut-hash-dedu.zig");
const CF = .{ .seeb = 4 << 20, .rawd = "raw", .part = ".part", .revz = 1000 };
pub const Estz = struct { cred: u32, micr: u64 };
pub fn estzWors(conf: cfgz.Conf, geoz: []const u8) Estz { const vend = base.vendFind(conf.vend_orde[0]) orelse return .{ .cred = 0, .micr = 0 }; var cred: u32 = 0; for ([_]base.Mode{ .plai, .rend, .prem }) |mode| cred += base.credRequ(vend, .{ .urlz = "", .mode = mode, .geoz = if (geoz.len > 0) geoz else conf.geoz_code_dflt }); return .{ .cred = cred, .micr = @as(u64, cred) * spen.pricOfzz(conf, vend) }; }
const Dryz = struct { mode: []const u8, see2: usize, sit2: bool, tie2: []const u8, wors_cred_urlz: u32, wors_micr_urlz: u64, note: []const u8 };
fn seedRead(ctx2: *const ctx3.Ctxz) ![]const []const u8 { var list: std.ArrayList([]const u8) = .empty; if (ctx2.args.urlz.len > 0) try list.append(ctx2.allo, ctx2.args.urlz); if (ctx2.args.seed.len > 0) { const text = std.Io.Dir.cwd().readFileAlloc(ctx2.iozz, ctx2.args.seed, ctx2.allo, .limited(CF.seeb)) catch return error.BadUsage; var iter = std.mem.splitScalar(u8, text, '\n'); while (iter.next()) |raws| { const line = std.mem.trim(u8, raws, " \t\r"); if (line.len == 0 or line[0] == '#') continue; try list.append(ctx2.allo, line); } } return list.toOwnedSlice(ctx2.allo); }
pub fn runzRunz(ctx2: *const ctx3.Ctxz) !u8 { const see2 = try seedRead(ctx2); if (see2.len == 0 and ctx2.args.smap.len == 0 and !ctx3.dbzzHave(ctx2)) return error.BadUsage;
if (!ctx2.args.live) { const estz = estzWors(ctx2.conf, ctx2.args.geoz); const dryz: Dryz = .{ .mode = "dry-run", .see2 = see2.len, .sit2 = ctx2.args.smap.len > 0, .tie2 = "own GET first, free", .wors_cred_urlz = estz.cred, .wors_micr_urlz = estz.micr, .note = "vendors only when own GET is blocked, only inside free credits unless --live --force; add --live to run" }; try ctx3.outz(ctx2, try ctx3.jsonOrzz(ctx2, dryz, try std.fmt.allocPrint(ctx2.allo, "dry-run | {d} seeds | worst case per URL {d} credits ({d} micro-USD) | add --live to run", .{ see2.len, estz.cred, estz.micr }))); return 0; }
var dbzz = try ctx3.dbzzOpen(ctx2); defer dbzz.close(); var real = try ctx3.realMake(ctx2); var wlk2 = walk.Walk.init(ctx2.init.gpa, ctx2.iozz, ctx2.conf, &dbzz, ctx2.dirz, false); defer wlk2.deinit(); wlk2.back = real.bac2(); wlk2.gozz = ctx2.args.forc; wlk2.geoz = ctx2.args.geoz; wlk2.foll = ctx2.args.foll; _ = try wlk2.walkSeed(see2); if (ctx2.args.smap.len > 0) _ = try wlk2.walkSmap(ctx2.args.smap); _ = try wlk2.walkRevi(CF.revz); const sum5 = try wlk2.walkRunz(if (ctx2.args.decl > 0) ctx2.args.decl else null);
const plai = try std.fmt.allocPrint(ctx2.allo, "run | seen {d} done {d} fail {d} skip {d} blocked {d} dead {d} {s}{s}", .{ sum5.seen, sum5.done, sum5.fail, sum5.skip, sum5.blok, sum5.dead, if (sum5.halt) "HALTED " else "", if (sum5.incm) "INCOMPLETE" else "" }); if (sum5.halt) clou.alerTryz(ctx2, "scra run halted", "circuit breaker tripped or spend stopped; check scra status"); try ctx3.outz(ctx2, try ctx3.jsonOrzz(ctx2, sum5, plai)); return exit.sumzCode(sum5.done, sum5.fail, sum5.blok, sum5.dead, sum5.halt, sum5.incm); }
pub fn runzExpo(ctx2: *const ctx3.Ctxz) !u8 { const fmt2: expo.Fmtz = if (std.mem.eql(u8, ctx2.args.fmtz, "csv")) .csv else if (std.mem.eql(u8, ctx2.args.fmtz, "jsonl")) .jso2 else return error.BadUsage; if (!ctx3.dbzzHave(ctx2)) { try ctx3.outz(ctx2, "no data yet"); return 0; } var dbzz = try ctx3.dbzzOpen(ctx2); defer dbzz.close(); var wbuf: [8192]u8 = undefined;
if (ctx2.args.outz.len == 0) { var wtrz = std.Io.File.stdout().writerStreaming(ctx2.iozz, &wbuf); _ = try expo.expoRunz(&dbzz, &wtrz.interface, fmt2, ctx2.allo); return 0; }
const temp = try std.fmt.allocPrint(ctx2.allo, "{s}{s}", .{ ctx2.args.outz, CF.part }); const cwdz = std.Io.Dir.cwd(); var filz = try cwdz.createFile(ctx2.iozz, temp, .{}); var wtrz = filz.writer(ctx2.iozz, &wbuf); const con2 = expo.expoRunz(&dbzz, &wtrz.interface, fmt2, ctx2.allo) catch |err3| { filz.close(ctx2.iozz); return err3; }; filz.close(ctx2.iozz); try cwdz.rename(temp, cwdz, ctx2.args.outz, ctx2.iozz); try ctx3.outz(ctx2, try std.fmt.allocPrint(ctx2.allo, "exported {d} rows to {s}", .{ con2, ctx2.args.outz })); return 0; }
const Cres = struct { urlz: []const u8, stat: []const u8, why2: []const u8 };
fn sigzOfzz(ctx2: *const ctx3.Ctxz, out2: pipe.Outc) !cana.Sigz { if (out2.hexz.len != 64) return error.Fail; var hexz: hash.Hexz = undefined; @memcpy(&hexz, out2.hexz[0..64]); const rawd = try std.fs.path.join(ctx2.allo, &.{ ctx2.dirz, CF.rawd }); const body = try file.fileLoad(ctx2.allo, ctx2.iozz, rawd, hexz, ctx2.conf.fetc_body_maxz); return cana.sigzMake(ctx2.allo, body); }
pub fn runzCana(ctx2: *const ctx3.Ctxz) !u8 { const live = ctx2.args.live; if (ctx2.args.adds.len > 0) { if (!live) { try ctx3.outz(ctx2, "dry-run | would fetch the URL and store its baseline signature | add --live to run"); return 0; } var dbzz = try ctx3.dbzzOpen(ctx2); defer dbzz.close(); const out2 = try pipe.pageFetc(ctx2.init.gpa, ctx2.allo, ctx2.iozz, ctx2.conf, &dbzz, ctx2.dirz, ctx2.args.adds, false); const code = exit.outcCode(out2.stat, out2.code); if (code != 0 or out2.hexz.len == 0) return if (code == 0) 1 else code; try cana.canaSetz(&dbzz, ctx2.allo, out2.urlz, try sigzOfzz(ctx2, out2), pipe.nowzMill(ctx2.iozz)); try ctx3.outz(ctx2, try std.fmt.allocPrint(ctx2.allo, "baseline saved: {s}", .{out2.urlz})); return 0; }
if (!ctx3.dbzzHave(ctx2)) { try ctx3.outz(ctx2, "no canaries yet: scra canary --add <url> --live"); return 0; } var dbzz = try ctx3.dbzzOpen(ctx2); defer dbzz.close(); const allz = try cana.canaAllz(&dbzz, ctx2.allo); if (!live) { try ctx3.outz(ctx2, try std.fmt.allocPrint(ctx2.allo, "dry-run | {d} canary URLs | add --live to run", .{allz.len})); return 0; }
var rslt: std.ArrayList(Cres) = .empty; var dri2: u32 = 0; var fai2: u32 = 0; for (allz) |item| { const out2 = pipe.pageFetc(ctx2.init.gpa, ctx2.allo, ctx2.iozz, ctx2.conf, &dbzz, ctx2.dirz, item.urlz, false) catch |err3| { fai2 += 1; try rslt.append(ctx2.allo, .{ .urlz = item.urlz, .stat = "fail", .why2 = @errorName(err3) }); continue; }; if (exit.outcCode(out2.stat, out2.code) != 0 or out2.hexz.len == 0) { fai2 += 1; try rslt.append(ctx2.allo, .{ .urlz = item.urlz, .stat = "fail", .why2 = out2.stat }); continue; } const curr = sigzOfzz(ctx2, out2) catch { fai2 += 1; try rslt.append(ctx2.allo, .{ .urlz = item.urlz, .stat = "fail", .why2 = "unreadable" }); continue; }; if (cana.sigzDrif(item.sigz, curr)) |why2| { dri2 += 1; try rslt.append(ctx2.allo, .{ .urlz = item.urlz, .stat = "drift", .why2 = why2 }); } else { try rslt.append(ctx2.allo, .{ .urlz = item.urlz, .stat = "ok", .why2 = "" }); } }
if (ctx2.args.json) { try ctx3.outz(ctx2, try std.json.Stringify.valueAlloc(ctx2.allo, rslt.items, .{})); } else { for (rslt.items) |item| try ctx3.outz(ctx2, try std.fmt.allocPrint(ctx2.allo, "{s} | {s} | {s}", .{ item.stat, item.urlz, item.why2 })); } return exit.canaCode(dri2, fai2); }
